import zipfile, xml.etree.ElementTree as ET, json, re

NS = {
    'ws': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r':  'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

path = "/sessions/local_7bmnmx7jfq/mnt/uploads/sample_model.xlsx"

def col_to_idx(col: str) -> int:
    idx = 0
    for c in col.upper():
        idx = idx * 26 + (ord(c) - ord('A') + 1)
    return idx - 1

def cell_ref_to_rc(ref: str):
    m = re.match(r'([A-Z]+)(\d+)', ref.upper())
    if not m:
        return None, None
    return int(m.group(2)) - 1, col_to_idx(m.group(1))

with zipfile.ZipFile(path) as z:
    names = z.namelist()

    # shared strings
    shared = []
    if 'xl/sharedStrings.xml' in names:
        tree = ET.parse(z.open('xl/sharedStrings.xml'))
        for si in tree.findall('.//{http://schemas.openxmlformats.org/spreadsheetml/2006/main}si'):
            parts = si.findall('.//{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')
            shared.append(''.join(p.text or '' for p in parts))

    # workbook → sheet names + rels
    wb = ET.parse(z.open('xl/workbook.xml'))
    wb_rels = ET.parse(z.open('xl/_rels/workbook.xml.rels'))
    rid_to_target = {
        r.get('Id'): r.get('Target')
        for r in wb_rels.findall('.//{http://schemas.openxmlformats.org/package/2006/relationships}Relationship')
    }
    sheet_names = []
    for sh in wb.findall('.//{http://schemas.openxmlformats.org/spreadsheetml/2006/main}sheet'):
        rid = sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
        target = rid_to_target.get(rid, '')
        sheet_names.append({'name': sh.get('name'), 'target': target})

    sheets_out = []
    for sinfo in sheet_names:
        target = sinfo['target']
        ws_path = f"xl/{target}" if not target.startswith('/') else target.lstrip('/')
        if ws_path not in names:
            ws_path2 = 'xl/' + target.split('/')[-1]
            if ws_path2 in names:
                ws_path = ws_path2
            else:
                continue
        ws = ET.parse(z.open(ws_path))

        # build a sparse dict of (row,col) -> value
        cells = {}
        max_row = 0
        max_col = 0
        for row_el in ws.findall('.//{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
            for c_el in row_el.findall('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c'):
                ref = c_el.get('r', '')
                t   = c_el.get('t', '')
                v_el = c_el.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}v')
                f_el = c_el.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}f')
                ri, ci = cell_ref_to_rc(ref)
                if ri is None:
                    continue
                max_row = max(max_row, ri)
                max_col = max(max_col, ci)
                if v_el is not None and v_el.text is not None:
                    raw = v_el.text
                    if t == 's':
                        idx = int(raw)
                        val = shared[idx] if idx < len(shared) else raw
                    elif t == 'b':
                        val = raw == '1'
                    else:
                        # try numeric
                        try:
                            fv = float(raw)
                            val = int(fv) if fv == int(fv) else fv
                        except ValueError:
                            val = raw
                    cells[(ri, ci)] = val
                elif f_el is not None:
                    cells[(ri, ci)] = None  # formula with no cached value

        # convert sparse to dense rows
        rows = []
        for r in range(max_row + 1):
            row = [cells.get((r, c)) for c in range(max_col + 1)]
            rows.append(row)

        # first non-empty row as headers heuristic
        headers = []
        header_row = 0
        for i, row in enumerate(rows[:5]):
            non_empty = [v for v in row if v is not None and str(v).strip()]
            if len(non_empty) >= 2:
                headers = [str(v) if v is not None else '' for v in row]
                header_row = i
                break

        pre_header = rows[:header_row] if header_row > 0 else []
        data_rows  = rows[header_row+1:] if headers else rows

        # cell_refs: map "A1" style label to value for first 10x10 region
        cell_refs = {}
        for (r,c), v in list(cells.items())[:200]:
            col_label = ''
            n = c + 1
            while n > 0:
                n, rem = divmod(n-1, 26)
                col_label = chr(65+rem) + col_label
            cell_refs[f"{col_label}{r+1}"] = str(v) if v is not None else ''

        sheets_out.append({
            'name': sinfo['name'],
            'headers': headers,
            'rows': data_rows,
            'pre_header_rows': pre_header,
            'detected_type': None,
            'periodicity': None,
            'row_count': len(data_rows),
            'col_count': max_col + 1,
            'cell_refs': cell_refs,
        })

    result = {
        'sheets': sheets_out,
        'source_format': 'xlsx',
        'source_file': path,
        'periodicity_summary': {},
    }
    print(json.dumps(result, indent=2)[:8000])  # truncate for preview
